#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> p(N + 1, 0);
    vector<vector<int>> children(N + 1);

    for (int i = 2; i <= N; i++) {
        cin >> p[i];
        children[p[i]].push_back(i);
    }

    const int LOG = 18;
    vector<vector<int>> up(LOG, vector<int>(N + 1, 0));

    for (int i = 2; i <= N; i++) up[0][i] = p[i];

    for (int j = 1; j < LOG; j++) {
        for (int i = 1; i <= N; i++) {
            up[j][i] = up[j - 1][up[j - 1][i]];
        }
    }

    vector<int> tin(N + 1), tout(N + 1);
    int timer = 0;

    stack<pair<int, int>> st;
    st.push({1, 0});

    while (!st.empty()) {
        auto [v, state] = st.top();
        st.pop();

        if (state == 0) {
            tin[v] = ++timer;
            st.push({v, 1});

            for (int i = (int)children[v].size() - 1; i >= 0; i--) {
                st.push({children[v][i], 0});
            }
        } else {
            tout[v] = timer;
        }
    }

    auto kth_ancestor = [&](int u, int k) {
        for (int j = 0; j < LOG; j++) {
            if (k & (1 << j)) u = up[j][u];
        }
        return u;
    };

    vector<int> node_at_tin(N + 1, 0);
    for (int v = 1; v <= N; v++) {
        node_at_tin[tin[v]] = v;
    }

    set<int> active;

    int Q;
    cin >> Q;

    while (Q--) {
        int type;
        cin >> type;

        if (type == 1) {
            int v, k;
            cin >> v >> k;

            int active_ancestor = 0;

            auto it = active.upper_bound(tin[v]);
            if (it != active.begin()) {
                --it;
                int cand_tin = *it;
                int cand = node_at_tin[cand_tin];

                if (tout[cand] >= tin[v]) {
                    if (cand != v) active_ancestor = cand;
                }
            }

            int ans;

            if (active_ancestor != 0) {
                if (k == 1) ans = active_ancestor;
                else ans = kth_ancestor(active_ancestor, k - 1);
            } else {
                ans = kth_ancestor(v, k);
            }

            cout << ans << '\n';
        } else {
            int v;
            cin >> v;

            bool has_active_ancestor = false;

            auto it = active.upper_bound(tin[v]);
            if (it != active.begin()) {
                --it;
                int cand_tin = *it;
                int cand = node_at_tin[cand_tin];

                if (tout[cand] >= tin[v]) {
                    has_active_ancestor = true;
                }
            }

            if (has_active_ancestor) continue;

            auto itL = active.lower_bound(tin[v]);
            auto itR = active.upper_bound(tout[v]);
            active.erase(itL, itR);

            active.insert(tin[v]);
            node_at_tin[tin[v]] = v;
        }
    }

    return 0;
}
